import React from 'react';
import {JsonEditor} from 'json-edit-react';

const JEditor = ({ data, setData }) => {
  const handleEdit = (edit) => {
    
        setData(edit.newData)
  };

  data = data ? data : {};  

  return (
    <JsonEditor
      data={data}
      //setData={setData}
      onEdit={handleEdit}
      onAdd={handleEdit}
      onDelete={handleEdit}
    />
    
  );
};

export default JEditor;
