import React from "react";
import { useState, useEffect } from "react";

// import "font-awesome/css/font-awesome.min.css";
import Alerts from "../htmlcomponents/Alerts";
import { useForm } from "react-hook-form";
import { yupResolver } from "@hookform/resolvers/yup";
import * as yup from "yup";
import api from "../api/Webcall";
import Spinner from "../htmlcomponents/Spinner";

import { GetAllDocTemplateList } from "../utilities/getallDocTempate";
import Table from "react-bootstrap/Table";
import { toast } from "react-toastify";

import {
  generateUUID,
  compressBase64,
  decompressBase64,
} from "../utilities/utils";

import appsettings from "../../appsettings.json";
import { getPostData } from "../utilities/apidataformatter";

const apiendpoints = appsettings.ApiEndpoints;

const CompanyId = localStorage.getItem("CompanyId");

const schema = yup.object().shape({
  txtTemplateName: yup.string().required("Pls enter the Name"),
});

//rfce - command
function DecoumntList({ displaychild, setTemplateId }) {
  // Const & Var

  const [doctempresbody, setdoctempresbody] = useState([]);
  const [alert, setAlert] = useState("");
  const [isLoading, setLoanding] = useState(false);
  const [UserStatusMaster, setUserStatusMaster] = useState([]);
  const [UserStatus, setUserStatus] = useState([]);

  const [screenid, setScreenid] = useState(0);
  const [IsCustomScr, setIsCustomScr] = useState(false);

  const {
    register,
    handleSubmit,
    formState: { errors },
    getValues,
    reset,
  } = useForm({
    resolver: yupResolver(schema),
  });

  // General Function

  const FetchAllDocTemplateList = async () => {
    const DocTemplateListResponse = await GetAllDocTemplateList();

    console.log(DocTemplateListResponse.body);
    setdoctempresbody(DocTemplateListResponse.body.docrpt);

    //console.log(ScreenListResponse.body.Screens);
  };

  const LoadTemplate = (Template) => {
    
    setTemplateId(Template.tmpltid);
    SetDocumentTemplateValue(Template);
    displaychild(true);
  };

  //   fetch combo values

  // Useeffect

  useEffect(() => {
    FetchAllDocTemplateList();
  }, []);

  useEffect(() => {}, [IsCustomScr]);

  // Event function start

  const onSubmitHandler = async (data) => {
    let scrpath = "";
    let TemplateId = data.txtTemplateId;

    if (data.txtTemplateId == undefined) TemplateId = "0";

    let frmData = {
      txtTemplateId: TemplateId,
      txtTemplateName: data.txtTemplateName,
    };

    const UpdTemplateDoc = apiendpoints.UpdTemplateDoc;

    setLoanding(true);

    //e.preventDefault();
    /* Header */
    const convID = generateUUID();
    const frmHdr = {
      convid: convID,
      tag: "UpdTemplateDoc",
      orgid: "",
      vendid: "0",
    };

    const token = localStorage.getItem("token");
    const reqHdr = { headers: { Authorization: `Bearer ${token}` } };
    const reqdata = { hdr: frmHdr, body: frmData };

    const CoreUrl = process.env.REACT_APP_FinXCoreUrl;

    console.log(reqdata);

    try {
      //
      const response = await api.post(
        UpdTemplateDoc,
        compressBase64(reqdata),
        reqHdr
      );

      const strResponse = JSON.parse(decompressBase64(response.data));

      console.log(strResponse);

      if (strResponse.hdr.rst == "FAILED" || strResponse.hdr.rst == "ERROR") {
        ShowAlert("Error", JSON.stringify(strResponse.fdr[0].rstmsg));
        setLoanding(false);
      } else {
        setTimeout(() => {
          console.log(strResponse.fdr);
          toast.success("Successfully updated");
          ShowAlert("Success", JSON.stringify(strResponse.fdr[0].rstmsg));
          setTimeout(() => {
            setAlert({
              AlertType: "null",
              message: "null",
            });
          }, 600);
          ResetDocumentTemplateValue();
          FetchAllDocTemplateList();
          setLoanding(false);
        }, 300);
      }
    } catch (err) {
      console.log(err.message);
      toast.error("Unable to process request");
      ShowAlert("Error", "Unable to process request");
      setLoanding(false);
    }
  };

  //---------------onSubmitHandler end------

  function SetDocumentTemplateValue(rowval) {
    // window.alert( rowval.IsActive);

    reset({
      txtTemplateId: rowval.tmpltid,
      txtTemplateName: rowval.tmpltname,
    });

    setScreenid(rowval.tmpltid);
  }

  function ResetDocumentTemplateValue() {
    reset({ txtTemplateId: "", txtTemplateName: "" });
  }

  const CheckboxhandleChange = (e) => {
    if (e.target.value == true) {
      setIsCustomScr(true);
    } else {
      setIsCustomScr(false);
    }
  };
  // Event Function End

  // Main Function

  const ShowAlert = (alertType, message) => {
    setAlert({
      AlertType: alertType,
      message: message,
    });
  };

  try {
    return (
      <>
        <section className="vh-100">
          <div className="container h-100">
            {/* <div className="row d-flex justify-content-center align-items-center h-100">
                  <div className="col-lg-12 col-xl-11"> */}
            <div className="card text-black" style={{ borderRadius: "25px" }}>
              <div className="card-header">
                <strong className="card-title">
                  Create New Document Tempate
                </strong>
              </div>
              <div className="card-body p-md-5">
                {isLoading ? <Spinner></Spinner> : ""}
                <Alerts alert={alert} />

                <form
                  onSubmit={handleSubmit(onSubmitHandler)}
                  autocomplete="off"
                >
                  <div className="row">
                    <div className="col-sm">
                      <div className="mb-3">
                        <label htmlFor="txtTemplateName" className="form-label">
                          {" "}
                          Document Template Name
                        </label>
                        <input
                          {...register("txtTemplateName")}
                          type="text"
                          className="form-control"
                        />
                        <p>{errors.txtScreenName?.message}</p>
                      </div>
                    </div>
                    <div className="col-sm">
                      <div className="mb-3">
                        <label htmlFor="txtTemplateId" className="form-label">
                          {" "}
                          Template Id
                        </label>
                        <input
                          {...register("txtTemplateId")}
                          type="text"
                          className="form-control"
                          disabled="disabled"
                          readonly="readonly"
                        />
                      </div>
                    </div>
                  </div>

                  <button type="submit" className="btn btn-primary">
                    Submit
                  </button>
                </form>
              </div>

              <Table striped bordered hover>
                <thead>
                  <tr>
                    <th>Id</th>
                    <th>Template</th>
                    <th>
                      <button
                        className="btn btn-success"
                        onClick={() => {
                          ResetDocumentTemplateValue();
                        }}
                      >
                        {" "}
                        <i className="bi bi-table"></i> Add{" "}
                      </button>
                    </th>
                  </tr>
                </thead>
                <tbody>
                  {doctempresbody.map((x) => {
                    return (
                      <tr>
                        <td>{x.tmpltid}</td>
                        <td>{x.tmpltname}</td>

                        <td>
                          <button
                            className="btn btn-primary"
                            onClick={() => {
                              LoadTemplate(x);
                            }}
                          >
                            {" "}
                            <i className="bi bi-pen"></i> Edit
                          </button>
                        </td>
                      </tr>
                    );
                  })}
                </tbody>
              </Table>
            </div>
          </div>
        </section>
      </>
    );
  } catch (error) {
    console.log(error.message);
  }
}

export default DecoumntList;
