import React, { useState, useEffect } from "react";
import PugEditor from "./PugEditor";
import JEditor from "./JEditor";
import HtmlPreview from "./HtmlPreview";
import Alerts from "../htmlcomponents/Alerts";
import api from "../api/Webcall";
import Spinner from "../htmlcomponents/Spinner";
import axios from "axios";
import { GetDocTemplate } from "../utilities/getallDocTempate";
import { toast } from "react-toastify";
import {
  generateUUID,
  compressBase64,
  decompressBase64,
} from "../utilities/utils";

import appsettings from "../../appsettings.json";
const apiendpoints = appsettings.ApiEndpoints;

const DocGen = ({ onGoBack, TemplateId }) => {
 
  const [data, setData] = useState({});
  const [template, setTemplate] = useState(" 4 h1 Name sukumar : #{name}");
  const [pdfcontent, setpdfcontent] = useState(null);
  const [activeTab, setActiveTab] = useState("pugEditor"); // State for active tab
  const [DocTempId, setDocTempId] = useState(TemplateId);

  const [alert, setAlert] = useState("");
  const [isLoading, setLoanding] = useState(false);

  const renderPDF = async (template, data) => {
    try {
      const response = await axios.post(
        "http://genrpt.saasis.co/genejspdf",
        { template, data },
        { responseType: "blob" }
      );
      const url = URL.createObjectURL(
        new Blob([response.data], { type: "application/pdf" })
      );
      setpdfcontent(url);
    } catch (error) {
      console.error("Error generating PDF:", error);
    }
  };

  const SaveDocTempate = async (template, data) => {
    let frmData = {
      txtTemplateId: TemplateId,
      txtTemplate: template,
      txtDataStru: data,
    };

    const saveTemplateDoc = apiendpoints.saveTemplateDoc;

    setLoanding(true);

    //e.preventDefault();
    /* Header */
    const convID = generateUUID();
    const frmHdr = {
      convid: convID,
      tag: "saveTemplateDoc",
      orgid: "",
      vendid: "0",
    };

    console.log(frmData);
    const token = localStorage.getItem("token");
    const reqHdr = { headers: { Authorization: `Bearer ${token}` } };
    const reqdata = { hdr: frmHdr, body: frmData };

    const CoreUrl = process.env.REACT_APP_FinXCoreUrl;

    console.log(reqdata);

    try {
      //
      const response = await api.post(
        saveTemplateDoc,
        compressBase64(reqdata),
        reqHdr
      );

      const strResponse = JSON.parse(decompressBase64(response.data));

      console.log(strResponse);

      if (strResponse.hdr.rst == "FAILED" || strResponse.hdr.rst == "ERROR") {
        ShowAlert("Error", JSON.stringify(strResponse.fdr[0].rstmsg));
        setLoanding(false);
      } else {
        setTimeout(() => {
          console.log(strResponse.fdr);
          toast.success("Successfully updated");
          ShowAlert("Success", JSON.stringify(strResponse.fdr[0].rstmsg));
          setTimeout(() => {
            setAlert({
              AlertType: "null",
              message: "null",
            });
          }, 600);

          setLoanding(false);
        }, 300);
      }
    } catch (err) {
      console.log(err.message);
      toast.error("Unable to process request");
      ShowAlert("Error", "Unable to process request");
      setLoanding(false);
    }
  };

  const onChange_ccmbScrId = (obj) => {
    //setScreenId(obj.value);
  };

  const Goback = () => {
    onGoBack(false);
  };

  // General Function

  const FetchDocTemplate = async () => {
    const DocTemplateListResponse = await GetDocTemplate(TemplateId); 
    setTemplate(DocTemplateListResponse.body.tmplt);    
    setData( DocTemplateListResponse.body.tmpltds);
  };

  // Useeffect

  useEffect(() => {
    FetchDocTemplate();
  }, []);

  const LoadTempate = (obj) => {
    //setScreenId(obj.value);
  };

  const ShowAlert = (alertType, message) => {
    setAlert({
      AlertType: alertType,
      message: message,
    });
  };

  try {
    return (
      <>
        {/* <div className="row d-flex justify-content-center align-items-center h-100">
                  <div className="col-lg-12 col-xl-11"> */}
        <div className="card text-black" style={{ borderRadius: "25px" }}>
          <div className="card-header">
            <strong className="card-title">Tempate Id : {DocTempId}</strong>
          </div>

          {/* Tab Navigation with Preview Button */}
          <div
            style={{
              display: "flex",
              justifyContent: "space-between",
              alignItems: "center",
            }}
          >
            <ul
              className="nav nav-tabs"
              id="docGenTabs"
              role="tablist"
              style={{ marginBottom: 0 }}
            >
              <li className="nav-item" role="presentation">
                <a
                  className={`nav-link ${
                    activeTab === "pugEditor" ? "active" : ""
                  }`}
                  id="pugEditor-tab"
                  data-bs-toggle="tab"
                  href="#pugEditor"
                  role="tab"
                  onClick={() => setActiveTab("pugEditor")}
                >
                  Pug Editor
                </a>
              </li>
              <li className="nav-item" role="presentation">
                <a
                  className={`nav-link ${
                    activeTab === "dataEditor" ? "active" : ""
                  }`}
                  id="dataEditor-tab"
                  data-bs-toggle="tab"
                  href="#dataEditor"
                  role="tab"
                  onClick={() => setActiveTab("dataEditor")}
                >
                  Data Editor
                </a>
              </li>
            </ul>
            <div>
              {isLoading ? <Spinner></Spinner> : ""}
              <Alerts alert={alert} />
            </div>
            <div>
              {" "}
              <button
                className="btn m-3 btn-success"
                onClick={() => renderPDF(template, data)}
              >
                {" "}
                Preview{" "}
              </button>
              <button
                className="btn m-3 btn-success"
                onClick={() => SaveDocTempate(template, data)}
              >
                {" "}
                Save{" "}
              </button>
              <button
                className="btn btn-primary"
                onClick={() => {
                  Goback();
                }}
              >
                Go Back
              </button>
            </div>
          </div>

          {/* Tab Content */}
          <div className="row mt-3">
            <div className="col-md-6">
              <div className="tab-content">
                <div
                  className={`tab-pane fade ${
                    activeTab === "pugEditor" ? "show active" : ""
                  }`}
                  id="pugEditor"
                  role="tabpanel"
                >
                  <PugEditor
                    template={template}
                    setTemplate={setTemplate}
                    language={"html"}
                  />
                </div>
                <div
                  className={`tab-pane fade ${
                    activeTab === "dataEditor" ? "show active" : ""
                  }`}
                  id="dataEditor"
                  role="tabpanel"
                >
                  <JEditor data={data} setData={setData} />
                </div>
              </div>
            </div>
            <div className="col-md-6">
              {/* Live Preview Section */}
              <div className="mt-4" style={{ display: "flex", gap: "20px" }}>
                <div style={{ flex: 1 }}>
                  <HtmlPreview
                    template={template}
                    data={data}
                    fileUrl={pdfcontent}
                  />
                </div>
              </div>
            </div>
          </div>
        </div>
      </>
    );
  } catch (error) {
    console.log(error.message);
  }
};

export default DocGen;
